head.b:skin:
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Bengali:wght@400;500;600;700;800&family=Hind+Siliguri:wght@400;500;600;700&display=swap');

:root {
  --background: hsl(210 20% 98%);
  --foreground: hsl(220 20% 10%);
  --surface: hsl(0 0% 100%);
  --border: hsl(214 20% 88%);
  --header-bg: hsl(220 25% 12%);
  --header-foreground: hsl(0 0% 95%);
  --news: hsl(215 80% 35%);
  --blog: hsl(152 55% 38%);
  --directory: hsl(270 40% 50%);
  --muted: hsl(210 15% 93%);
  --muted-foreground: hsl(220 10% 45%);
  --shadow: 0 18px 40px rgba(21, 37, 65, 0.08);
  --radius: 18px;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background:
    radial-gradient(circle at top right, rgba(37, 99, 235, 0.08), transparent 28%),
    radial-gradient(circle at bottom left, rgba(124, 58, 237, 0.07), transparent 24%),
    var(--background);
  color: var(--foreground);
  font-family: 'Hind Siliguri', sans-serif;
  line-height: 1.7;
}

a { color: var(--news); text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; border-radius: 16px; }

.page-shell { min-height: 100vh; }
.container {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
}

.topbar {
  background: var(--header-bg);
  color: var(--header-foreground);
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.topbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 18px 0;
}

.brand-block h1,
.brand-block h2,
.brand-block .title {
  margin: 0;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  font-weight: 800;
  letter-spacing: -0.02em;
}

.brand-block .description {
  margin-top: 6px;
  color: rgba(255,255,255,0.72);
  font-size: 0.96rem;
}

.quick-search {
  min-width: min(360px, 100%);
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 999px;
  padding: 12px 18px;
  color: rgba(255,255,255,0.82);
  text-align: right;
}

.nav-wrap {
  background: rgba(255,255,255,0.96);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}

.nav-chip-list {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 14px 0;
}

.nav-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 999px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  color: var(--foreground);
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}

.chip-news { border-color: color-mix(in srgb, var(--news) 35%, white); }
.chip-blog { border-color: color-mix(in srgb, var(--blog) 35%, white); }
.chip-directory { border-color: color-mix(in srgb, var(--directory) 35%, white); }

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(300px, 0.75fr);
  gap: 24px;
  padding: 28px 0;
}

.hero-card,
.content-card,
.sidebar-card,
.footer-card {
  background: rgba(255,255,255,0.92);
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) + 4px);
  box-shadow: var(--shadow);
}

.hero-card {
  padding: 28px;
  background:
    linear-gradient(135deg, rgba(26, 82, 153, 0.06), rgba(18, 125, 81, 0.05)),
    rgba(255,255,255,0.94);
}

.hero-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-radius: 999px;
  background: rgba(37, 99, 235, 0.08);
  color: var(--news);
  font-weight: 700;
  font-size: 0.92rem;
}

.hero-card h3 {
  margin: 18px 0 10px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: clamp(1.8rem, 4vw, 3rem);
  line-height: 1.15;
}

.hero-card p {
  margin: 0;
  color: var(--muted-foreground);
  font-size: 1rem;
}

.hero-side {
  display: grid;
  gap: 16px;
}

.hero-mini {
  padding: 20px;
  position: relative;
  overflow: hidden;
}

.hero-mini::before {
  content: '';
  position: absolute;
  inset: auto -32px -32px auto;
  width: 120px;
  height: 120px;
  border-radius: 999px;
  background: rgba(124, 58, 237, 0.08);
}

.hero-mini.blog-accent::before { background: rgba(22, 163, 74, 0.08); }

.section-title {
  margin: 0 0 18px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: 1.4rem;
  font-weight: 800;
}

.content-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 24px;
  padding-bottom: 36px;
}

.content-card { padding: 24px; }
.sidebar-card { padding: 20px; }

.post,
.post-outer {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  margin-bottom: 18px;
  transition: transform .2s ease, box-shadow .2s ease;
}

.post:hover,
.post-outer:hover {
  transform: translateY(-2px);
  box-shadow: 0 20px 34px rgba(22, 37, 66, 0.08);
}

h2.post-title,
.post-title {
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: clamp(1.3rem, 3vw, 2rem);
  line-height: 1.25;
  margin: 0 0 12px;
}

.post-meta,
.byline {
  color: var(--muted-foreground);
  font-size: 0.92rem;
  margin-bottom: 12px;
}

.post-body,
.post-snippet,
.entry-content {
  color: var(--foreground);
  font-size: 1rem;
}

.widget {
  margin-bottom: 20px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border);
}

.widget:last-child { border-bottom: 0; margin-bottom: 0; padding-bottom: 0; }

.widget h3,
.widget h2 {
  margin: 0 0 14px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: 1.05rem;
  font-weight: 800;
}

.Label a,
.PopularPosts .item-title a,
.LinkList a {
  display: inline-flex;
  margin: 0 8px 8px 0;
  padding: 8px 12px;
  background: var(--muted);
  border-radius: 999px;
  color: var(--foreground);
  font-size: 0.92rem;
}

.footer-shell {
  margin: 0 0 32px;
}

.footer-card {
  padding: 24px;
  background: var(--header-bg);
  color: var(--header-foreground);
}

.footer-card a { color: rgba(255,255,255,0.92); }
.copyright { color: rgba(255,255,255,0.68); font-size: 0.92rem; }

@media (max-width: 980px) {
  .hero,
  .content-grid { grid-template-columns: 1fr; }
  .quick-search { display: none; }
}

@media (max-width: 640px) {
  .container { width: min(100% - 20px, 1180px); }
  .topbar-inner { padding: 16px 0; }
  .hero-card,
  .content-card,
  .sidebar-card,
  .footer-card,
  .post,
  .post-outer { padding: 18px; }
  .nav-chip-list { gap: 8px; }
  .nav-chip { width: 100%; justify-content: center; }
}
